/**
 * The typed error Swift sees. Mirrors `StudioError` (each variant carries a
 * machine `code` via its name plus a readable message). Secrets are never in
 * a message (PATs live in the Keychain and are redacted in any snippet).
 */
public enum FfiError: Swift.Error {

    
    
    case NotInitialized(message: String
    )
    case InvalidArgument(message: String
    )
    case Command(code: String, message: String
    )
    case Io(message: String
    )
    case Audio(message: String
    )
    case Gen(message: String
    )
    case RateLimited(message: String
    )
    case ConfirmationRequired(message: String
    )
    case Unsupported(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotInitialized(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidArgument(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Command(
            code: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Io(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Audio(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Gen(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .RateLimited(
            message: try FfiConverterString.read(from: &buf)
            )
        case 8: return .ConfirmationRequired(
            message: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Unsupported(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NotInitialized(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidArgument(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Command(code,message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Io(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Audio(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Gen(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .RateLimited(message):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .ConfirmationRequired(message):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Unsupported(message):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


